157: const game={
158:   isCameraLocked(){ return !!(st&&st.tutorial); },
159:   onTap(e){
160:     if(!st||st.over)return;
161:     const r=renderer.renderer.domElement.getBoundingClientRect();
162:     const nx=((e.clientX-r.left)/r.width)*2-1, ny=-((e.clientY-r.top)/r.height)*2+1;
163:     const pt=renderer.pick(nx,ny);
164:     // A tap that projects off the map (edge of screen, skewed aspect) must never
165:     // become a move order to nowhere.
166:     if(!pt||!isFinite(pt.x)||!isFinite(pt.z)||Math.abs(pt.x)>WORLD/2||Math.abs(pt.z)>WORLD/2) return;
167:     // Thumb-friendly pick radius: generous on phones, tighter in battles.
168:     // Two passes so a unit standing beside a building is still reachable with
169:     // a fat thumb — buildings only win when nothing else is under the finger.
170:     const pickR=st.tutorial?3.4:2.2;
171:     let unit=null,ud=1e9, bld=null,bd=1e9;
172:     for(const en of st.entities){ if(en.dead||en.cat==='proj')continue;
173:       if(st.fog&&en.owner===1){ const gx=Math.max(0,Math.min(GRID-1,Math.floor(en.x/CELL+GRID/2))),gz=Math.max(0,Math.min(GRID-1,Math.floor(en.z/CELL+GRID/2))); if(!map.visible[0][gz*GRID+gx]&&en.cat!=='bld') continue; }
174:       const d=Math.hypot(en.x-pt.x,en.z-pt.z)-(en.cat==='bld'?(en.size||2):0);
175:       if(d>pickR) continue;
176:       if(en.cat==='unit'){ if(d<ud){ud=d;unit=en;} } else if(en.cat==='bld'){ if(d<bd){bd=d;bld=en;} }
177:     }
178:     let best = st.tutorial ? (unit||bld) : (unit&&ud<bd+1.2 ? unit : (bld||unit));
179:     const mine=[...sel].map(id=>byId(st,id)).filter(u=>u&&!u.dead&&u.owner===0);
180:     if(best&&best.owner===0){ // select
