182:     } else if(best&&best.owner===1){ // attack / target
183:       if(mine.length){ mine.forEach((u,i)=>{ if(u.cat==='unit'){ if(u.type==='peasant'&&best.cat==='bld')return; orderAttack(st,u,best.id);} }); sfx.move(); toast('⚔️ Attack!'); }
184:       else { sel=new Set([best.id]); renderSel(); }
185:     } else if(best&&best.owner===2){ /* resource handled below */ }
186:     else {
187:       // resource node near tap?
188:       let node=null,nk=null,ni=-1;
189:       const all=[['tree',map.trees],['gold',map.gold]];
190:       for(const [k,arr] of all) arr.forEach((n,i)=>{ if(n.amount>0&&Math.hypot(n.x-pt.x,n.z-pt.z)<2.5){node=n;nk=k;ni=i;} });
191:       const peas=mine.filter(u=>u.type==='peasant');
192:       if(node&&peas.length){ peas.forEach(p=>orderGather(st,map,p,nk==='gold'?'gold':'tree',ni)); sfx.move(); toast(nk==='gold'?'⛏️ Mine gold!':'🪓 Chop wood!'); }
193:       else if(mine.length&&mine.some(u=>u.cat==='unit')){ // move with formation
194:         mine.filter(u=>u.cat==='unit').forEach((u,i)=>{ const ox=(i%3-1)*1.8,oz=Math.floor(i/3)*1.8; orderMove(st,u,pt.x+ox,pt.z+oz,false); });
195:         sfx.move();
196:       } else if(!best){ sel.clear(); renderSel(); }
197:     }
198:   },
199:   onLongPress(){ // open build menu for selected peasant / show build card
200:     const mine=[...sel].map(id=>byId(st,id)).filter(u=>u&&!u.dead&&u.owner===0);
201:     if(mine.some(u=>u.type==='peasant')){ renderSel(true); toast('🔨 Choose a building below'); }
202:     else toast('Select a Peasant (long-press = build menu)');
203:   }
