312: // ---- main loop: fixed 10Hz sim + render ----
313: function loop(now){
314:   if(!running)return;
315:   requestAnimationFrame(loop);
316:   let dt=(now-lastT)/1000; lastT=now; dt=Math.min(dt,0.1);
317:   const time=now/1000;
318:   if(!paused&&!st.over){
319:     acc+=dt*st.speed;
320:     const STEP=0.1; let n=0;
321:     while(acc>=STEP&&n<5){ tick(st,map,STEP); st.events.forEach(ev=>{ if(ev.t==='hit')renderer.hit(ev.x,ev.z); if(ev.t==='gather'){ if(ev.kind==='gold')sfx.coin(); else sfx.chop(); } if(ev.t==='toast')toast(ev.msg); if(ev.t==='bell')sfx.bell(); if(ev.t==='season'){ renderer.setSeason(ev.season); toast('❄️ Winter falls — farms thin, the forest sleeps.',4200); } }); acc-=STEP; n++;
322:       aiAcc+=STEP; if(aiAcc>2){aiAcc=0; if(!st.tutorial){try{aiTick(st,map);}catch(err){console.warn(err);}} }
323:     }
324:     saveAcc+=dt; if(saveAcc>15){saveAcc=0; if(!st.tutorial)saveGame(st,map);}
325:     if(acc>STEP*5) acc=STEP*5;
326:   }
327:   renderer.sync(st,map,sel,time);
328:   hud();
329:   selAcc+=dt; if(selAcc>=0.5){ selAcc=0; renderSelLive(); }
330:   // Mission 1 tutorial: evaluated after the sim step, no fail state, no AI.
331:   // The UI keeps refreshing after completion so the bar settles on "complete".
332:   if(mission){
333:     const ctx=makeCtx(st,map,sel,mission.history,0);
334:     if(!mission.done){
335:       for(const ev of mission.tick(st,ctx,st.t)){
336:         if(ev.type==='step-done'){ sfx.coin(); toast(`✅ ${ev.step.title} — done!`,2200); }
337:         if(ev.type==='step-start') missionAssist(ev.step.id);
338:         if(ev.type==='mission-done'){ sfx.win(); onMissionComplete(ev.reward); }
339:       }
340:     }
341:     uiAcc+=dt; if(uiAcc>=0.2){ uiAcc=0; updateCoachMark(); tutUI.update(mission,ctx); }
342:   }
343:   if(st.over&&!st._end&&!st.tutorial){ st._end=true; endGame(st.over.win,st.over.draw); }
344: }
345: function onMissionComplete(reward){
346:   const prof=getProfile();
347:   markMissionComplete(prof,MISSION1.id);
348:   addAch(prof,reward.achievement);
349:   setProfile(prof);
350:   // Reward is real: it lands in the kingdom you carry into the battle.
351:   st.res[0].gold+=reward.gold; st.res[0].wood+=reward.wood;
352:   tutUI.celebrate(reward);
353: }
