157:     if(!tgt||tgt.dead){e.order={kind:'idle'};return;}
158:     const range=(UNITS[e.type].range||1.6)*(e.type==='archer'?(fm.range??1):1);
159:     const reach=range+(tgt.cat==='bld'?(tgt.size||0):0);
160:     const d=Math.hypot(tgt.x-e.x,tgt.z-e.z);
161:     if(d<=reach){
162:       if(e.cool<=0){
163:         e.cool=e.type==='archer'?1.3:1.0;
164:         let dmg=e.dmg;
165:         if(e.chargeHit){ dmg*=1.5; e.chargeHit=false; }
166:         if(e.type==='archer') fireProjectile(st,e,tgt,dmg);
167:         else { dealDamage(st,e,tgt,dmg); st.events.push({t:'hit',x:tgt.x,z:tgt.z}); }
168:         e.face=tgt;
169:       }
170:     } else {
171:       if(!o.path||(o.chaseT??0)<=0){
172:         o.path=findPath(w2g(e.x),w2g(e.z),w2g(tgt.x),w2g(tgt.z),blocked)||[{x:tgt.x,z:tgt.z}];
173:         o.pi=0; o.chaseT=0.5;
174:       }
175:       o.chaseT-=dt;
176:       const wp=o.path[o.pi];
177:       if(wp&&moveToward(e,wp,dt)){ o.pi++; if(o.pi>=o.path.length){o.path=null;o.chaseT=0;} }
178:       if(Math.hypot(tgt.x-e.x,tgt.z-e.z)>reach+14) e.order={kind:'idle'};
179:     }
180:     return;
181:   }
182:   if(o.kind==='gather'){
183:     const node=o.node; // {kind:'tree'|'gold', ref}
184:     const arr=o.kind2==='gold'?map.gold:map.trees;
185:     const n=arr[o.idx];
186:     if(!n||n.amount<=0){ // find another
187:       const ni=findResource(map,e.x,e.z,o.kind2,st);
188:       if(ni>=0){o.idx=ni;} else {e.order={kind:'idle'};e.carry=null;return;}
189:       return;
190:     }
191:     const d=Math.hypot(n.x-e.x,n.z-e.z);
192:     if(e.carryAmt>0){ // return home
193:       const hall=nearestHall(st,e.owner,e.x,e.z);
194:       if(!hall){e.order={kind:'idle'};return;}
195:       if(Math.hypot(hall.x-e.x,hall.z-e.z)<4){
196:         const rkey=o.kind2==='gold'?'gold':'wood';
197:         const mult=(o.kind2==='gold'?(fm.gold??1):(fm.wood??1))*(fm.gather??1);
198:         st.res[e.owner][rkey]+=e.carryAmt*mult; e.carryAmt=0; e.carry=null;
199:         st.events.push({t:'gather',x:e.x,z:e.z,kind:o.kind2});
200:       } else moveToward(e,hall,dt);
201:       return;
202:     }
203:     if(d<2.2){ e.gatherT=(e.gatherT||0)+dt; if(e.gatherT>1.2){e.gatherT=0; const take=Math.min(UNITS.peasant.gather,n.amount); n.amount-=take; e.carryAmt=take; e.carry=o.kind2;
204:       if(o.kind2==='tree'&&!st.tutorial) addWrath(st,e,take); } }
205:     else moveToward(e,n,dt);
206:     return;
207:   }
208:   if(o.kind==='build'){
209:     const b=byId(st,o.id);
210:     if(!b||b.dead){e.order={kind:'idle'};return;}
211:     if(Math.hypot(b.x-e.x,b.z-e.z)<b.size+1.5){ b.builder=true; e.building=true; if(b.done){e.order={kind:'idle'};e.building=false;} }
212:     else { e.building=false; moveToward(e,b,dt); }
213:     return;
214:   }
215: }
