217: function moveToward(e,wp,dt){
218:   if(e.root>0) return false;
219:   const dx=wp.x-e.x,dz=wp.z-e.z,d=Math.hypot(dx,dz);
220:   if(d<0.4) return true;
221:   const sp=(e.speed||5)*(e.buff?.charge>0?2.2:1)*dt;
222:   e.x+=dx/d*Math.min(sp,d); e.z+=dz/d*Math.min(sp,d);
223:   e.face={x:wp.x,z:wp.z};
224:   return d<0.6;
225: }
226: export function orderMove(st,e,x,z,attack){
227:   // formation offsets applied by caller
228:   e.order={kind:attack?'attackmove':'move',x,z,path:null,pi:0}; e.building=false;
229: }
230: export function orderAttack(st,e,id){ e.order={kind:'attack',id}; e.building=false; }
231: export function orderGather(st,map,e,kind2,idx){ e.order={kind:'gather',kind2,idx}; }
232: export function orderBuild(st,e,id){ e.order={kind:'build',id}; }
233: export function findResource(map,x,z,kind2,st,maxR=Infinity){
234:   const arr=kind2==='gold'?map.gold:map.trees;
235:   let bi=-1,bd=maxR*maxR;
236:   for(let i=0;i<arr.length;i++){ if(arr[i].amount<=0)continue; const d=(arr[i].x-x)**2+(arr[i].z-z)**2; if(d<bd){bd=d;bi=i;} }
237:   return bi;
238: }
239: export function nearestHall(st,owner,x,z){
240:   let best=null,bd=1e9;
241:   for(const e of st.entities){ if(e.dead||e.owner!==owner||e.cat!=='bld')continue; if(e.type!=='townhall'&&e.type!=='farm')continue; if(!e.done)continue; const d=(e.x-x)**2+(e.z-z)**2; if(d<bd){bd=d;best=e;} }
242:   return best;
243: }
244: export function spawnHero(st,owner){
245:   const th=st.entities.find(e=>!e.dead&&e.owner===owner&&e.type==='townhall');
246:   if(!th) return null;
247:   const fac=owner===0?st.playerFaction:st.aiFaction, fm=factionMult(fac), u=UNITS.hero, H=heroFor(fac);
248:   const hp=u.hp*fm.hp, dmg=u.dmg*fm.dmg;
249:   const hero=addEntity(st,{cat:'unit',type:'hero',owner,faction:fac,heroName:H.name,x:th.x+4,z:th.z-4,hp,maxHp:hp,dmg,armor:u.armor,range:u.range,speed:u.speed*(fm.speed??1),sight:u.sight,armorPierce:u.armorPierce||0,level:1,xp:0,order:null,carry:null,carryAmt:0,cool:0});
250:   st.events.push({t:'toast',msg:owner===0?`👑 ${H.name} answers your call!`:`👑 Enemy ${H.name} takes the field!`});
251:   return hero;
252: }
253: export function addWrath(st,e,take){
254:   const fk=e.owner===0?st.playerFaction:st.aiFaction;
255:   st.wrath[e.owner]=Math.min(100,(st.wrath[e.owner]||0)+take*(fk==='elf'?0.05:0.1));
256:   const old=st.wrathTier[e.owner]||0, tier=Math.floor(st.wrath[e.owner]/25);
