264:     addEntity(st,{cat:'unit',type:'treant',owner:2,wildOwner:src.owner,x:src.x+Math.cos(a)*r,z:src.z+Math.sin(a)*r,hp:u.hp,maxHp:u.hp,dmg:u.dmg,armor:u.armor,range:u.range,speed:u.speed,sight:u.sight,armorPierce:0,order:{kind:'attack',id:src.id},carry:null,carryAmt:0,cool:0});
265:   }
266:   st.events.push({t:'toast',msg:'🌲 The wild sends treants!'});
267: }
