23:   const faction = st.aiFaction || 'undead';
24:   const fm = factionMult(faction);
25:   const meleeCount = 2 + wave * 2;
26:   const rangedCount = wave >= 3 ? Math.floor(wave / 2) : 0;
27:   const types = ['warrior', 'archer'];
28:   for (let i = 0; i < meleeCount + rangedCount; i++) {
29:     const type = i < meleeCount ? types[0] : types[1];
30:     const u = UNITS[type];
31:     // Spread spawns across the four map edges, keeping all coordinates in-world.
32:     const edge = (i + wave * 3) % 4;
33:     const offset = (((i * 17 + wave * 11) % 55) - 27);
34:     const x = edge < 2 ? offset : (edge === 2 ? -43 : 43);
35:     const z = edge < 2 ? (edge === 0 ? -43 : 43) : offset;
36:     const enemy = addEntity(st, {
37:       cat: 'unit', type, owner: 1, faction,
38:       x, z, hp: u.hp * fm.hp, maxHp: u.hp * fm.hp,
39:       dmg: u.dmg * (type === 'archer' ? (fm.archer ?? fm.dmg) : fm.dmg),
40:       armor: u.armor, range: u.range, speed: u.speed * fm.speed,
41:       sight: u.sight, armorPierce: u.armorPierce || 0,
42:       order: null, carry: null, carryAmt: 0, cool: 0,
43:     });
44:     orderMove(st, enemy, hall.x, hall.z, true);
