const E=await import("./src/core/engine.js"),W=await import("./src/world/world.js"),S=await import("./src/sim/sim.js"),D=await import("./src/modes/defense.js"),{BUILDINGS}=await import("./src/buildings/data.js");
for(const towerCount of [0,8,16]){
 const st=E.makeState({faction:"human",aiFaction:"undead",ai:"expander",fog:"off",speed:1}); const map=W.genMap(42);
