 for(let i=0;i<towerCount;i++){const a=i/towerCount*Math.PI*2; st.entities.push({id:9000+i,cat:"bld",type:"tower",owner:0,faction:"human",x:-30+Math.cos(a)*10,z:-30+Math.sin(a)*10,hp:600,maxHp:600,done:true,size:1.6,cool:0});}
