 for(let n=0;n<15000&&!st.over;n++){S.tick(st,map,.1);D.updateDefense(st,map,.1);simTime+=.1;const active=st.entities.filter(e=>e.owner===1&&e.cat==="unit"&&!e.dead);maxIdle=Math.max(maxIdle,active.filter(e=>!e.order||e.order.kind==="idle").length);if(simTime>1000)break;}
